    "items": [
      {
        "id": "A",
        "available_quantity": "$$q_A$$",
        "unit_weight_tons": "$$w_A$$"
      },
      {
        "id": "B",
        "available_quantity": "$$q_B$$",
        "unit_weight_tons": "$$w_B$$"
      },
      {
        "id": "C",
        "available_quantity": "$$q_C$$",
        "unit_weight_tons": "$$w_C$$"
      },
      {
        "id": "D",
        "available_quantity": "$$q_D$$",
        "unit_weight_tons": "$$w_D$$"
      },
      {
        "id": "E",
        "available_quantity": "$$q_E$$",
        "unit_weight_tons": "$$w_E$$"
      }
    ]
  },
  "containers": {
    "index_set_size": "$$K$$",
    "meaning": "candidate containers indexed by $$k \\in \\mathcal{K} = \\{1,2,\\dots,K\\}$$",
    "maximum_load_tons": "$$U$$",
    "minimum_load_tons_if_used": "$$L$$"
  },
  "compatibility_rules": {
    "meaning": "intra-container packaging rules indexed by $$r \\in \\mathcal{R}$$",
    "rules": [
      {
        "trigger_product": "A",
        "required_product": "C",
        "minimum_required_quantity": "$$\\alpha_{A,C}$$"
      }
    ]
  },
  "product_specific_minimums_if_container_is_used": {
    "meaning": "per-used-container minimum quantities for designated products",
    "minimum_units": {
      "D": "$$m_D$$"
    }
  },
  "objective": {
    "meaning": "minimize the number of used containers"
  }
}

Output Format
{
  "objective_value": {
    "meaning": "minimum number of used containers",
    "symbol": "$$z^*$$"
  },
  "container_plan": {
    "index_set": "$$\\mathcal{K}$$",
    "items": [
      {
        "container_id": "$$k$$",
        "used": "$$y_k$$",
        "loads_by_product": {
          "A": "$$x_{A k}$$",
          "B": "$$x_{B k}$$",
          "C": "$$x_{C k}$$",
          "D": "$$x_{D k}$$",
          "E": "$$x_{E k}$$"
        },
        "total_weight_tons": "$$W_k$$"
      }
    ]
  }
}

